<template><div class='space-y-4'><BaseCard><h2 class='text-xl mb-2'>IA do Prontuário #{{ id }}</h2><UploadZone :disabled='loadingUpload' :filename='filename' :preview='preview' @select='onSelect' @analyze='upload'/><ErrorState v-if='error' :message='error'/></BaseCard><BaseCard v-if='analysis'><ResultView :value='analysis' :onBack='()=>{}' /><div class='mt-4 space-y-2'><BaseInput v-model='validation.doctor_final_assessment' placeholder='doctor_final_assessment'/><BaseInput v-model='validation.doctor_notes' placeholder='doctor_notes'/><select v-model='validation.doctor_agreement' class='border rounded-xl px-3 py-2'><option>YES</option><option>NO</option><option>PARTIAL</option></select><BaseButton @click='validateAI'>Validar IA</BaseButton></div></BaseCard></div></template>
<script setup>import { ref,reactive } from 'vue';import { useRoute } from 'vue-router';import UploadZone from '../components/UploadZone.vue';import ResultView from '../components/ResultView.vue';import BaseCard from '../components/BaseCard.vue';import BaseInput from '../components/BaseInput.vue';import BaseButton from '../components/BaseButton.vue';import ErrorState from '../components/ErrorState.vue';import { documentService } from '../services/documentService';import { aiService } from '../services/aiService';
const id=useRoute().params.id;const file=ref(null),filename=ref(''),preview=ref(''),loadingUpload=ref(false),error=ref(''),analysis=ref(null),analysisId=ref(null);
const validation=reactive({doctor_agreement:'YES',doctor_final_assessment:'',doctor_notes:''})
const onSelect=(f)=>{file.value=f;filename.value=f.name;preview.value=URL.createObjectURL(f)}
const upload=async()=>{try{loadingUpload.value=true;error.value='';const doc=await documentService.upload({file:file.value,medical_record_id:id});const result=await aiService.analyze({medical_record_id:id,document_id:doc.id||doc.document_id});analysis.value=result;analysisId.value=result.id}catch{error.value='Erro no fluxo de IA'}finally{loadingUpload.value=false}}
const validateAI=async()=>{if(!analysisId.value)return;try{await aiService.validate(analysisId.value,validation);alert('IA validada')}catch{error.value='Erro ao validar IA'}}
</script>
